=== nova_analytics_id/tokens/colors.css ===
:root {
  /* Brand */
  --nova-indigo: #4F46E5;
  --nova-indigo-dark: #3730A3;
  --nova-indigo-darker: #1E1B4B;
  --nova-spark: #22D3EE;
  --nova-spark-light: #67E8F9;
  --nova-amber: #F5A623;

  /* Neutral */
  --nova-ink: #0F172A;
  --nova-gray-900: #0F172A;
  --nova-gray-700: #334155;
  --nova-gray-500: #64748B;
  --nova-gray-300: #CBD3E1;
  --nova-gray-100: #EEF1F6;
  --nova-gray-50: #F8FAFC;
  --nova-white: #FFFFFF;

  /* Semantic */
  --nova-success: #16A34A;
  --nova-warning: #F59E0B;
  --nova-danger: #DC2626;
  --nova-info: #4F46E5;
}
=== nova_analytics_id/tokens/typography.css ===
:root {
  --nova-font-display: 'Space Grotesk', 'Sora', system-ui, -apple-system, sans-serif;
  --nova-font-body: 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;
  --nova-font-mono: 'JetBrains Mono', 'SFMono-Regular', Menlo, Consolas, monospace;

  --nova-text-xs: 0.75rem;
  --nova-text-sm: 0.875rem;
  --nova-text-base: 1rem;
  --nova-text-lg: 1.125rem;
  --nova-text-xl: 1.5rem;
  --nova-text-2xl: 2rem;
  --nova-text-3xl: 2.75rem;

  --nova-weight-regular: 400;
  --nova-weight-medium: 500;
  --nova-weight-bold: 700;
}

/* Usage
  Display / headings   -> var(--nova-font-display), weight 500-700
  Body / UI copy        -> var(--nova-font-body), weight 400-500
  Metrics / tables / code -> var(--nova-font-mono), weight 400-500
*/
=== nova_analytics_id/tokens/colors.json ===
{
  "brand": {
    "indigo": { "value": "#4F46E5", "role": "Primary brand color — CTAs, links, active states" },
    "indigo-dark": { "value": "#3730A3", "role": "Hover/pressed states, primary text on light" },
    "indigo-darker": { "value": "#1E1B4B", "role": "Dark-mode surfaces, deep backgrounds" },
    "spark": { "value": "#22D3EE", "role": "Accent — highlights, the 'nova' burst, data emphasis" },
    "spark-light": { "value": "#67E8F9", "role": "Accent tint for hover/backgrounds" },
    "amber": { "value": "#F5A623", "role": "Secondary accent — used sparingly for warmth/callouts" }
  },
  "neutral": {
    "ink": { "value": "#0F172A", "role": "Primary text, dark-mode background" },
    "gray-900": { "value": "#0F172A" },
    "gray-700": { "value": "#334155", "role": "Secondary text" },
    "gray-500": { "value": "#64748B", "role": "Muted text, subtitles" },
    "gray-300": { "value": "#CBD3E1", "role": "Borders, dividers" },
    "gray-100": { "value": "#EEF1F6", "role": "Subtle backgrounds, cards" },
    "gray-50": { "value": "#F8FAFC", "role": "Page background" },
    "white": { "value": "#FFFFFF" }
  },
  "semantic": {
    "success": { "value": "#16A34A" },
    "warning": { "value": "#F59E0B" },
    "danger": { "value": "#DC2626" },
    "info": { "value": "#4F46E5" }
  },
  "dataviz-categorical": [
    "#4F46E5",
    "#22D3EE",
    "#F5A623",
    "#16A34A",
    "#DC2626",
    "#8B5CF6",
    "#0EA5E9",
    "#64748B"
  ]
}

