        900: "#78350F",
      },
      // Cyan is the spark accent; indigo/blue/purple/teal fold onto the brand
      // scales so no stray off-palette hue can leak back into the UI.
      cyan: accent,
      teal: accent,
      indigo: primary,
      blue: primary,
      purple: primary,
      pink: primary,
